import{_ as c,r as t,o as l,c as i,e,a as s,s as u,d as a}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Ответы и представления - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Базовые ответы","slug":"базовые-ответы","link":"#базовые-ответы","children":[{"level":4,"title":"Возврат строк из CMS-метода","slug":"возврат-строк-из-cms-метода","link":"#возврат-строк-из-cms-метода","children":[]},{"level":4,"title":"Возврат строк из AJAX-обработчиков","slug":"возврат-строк-из-ajax-обработчиков","link":"#возврат-строк-из-ajax-обработчиков","children":[]},{"level":4,"title":"Возврат строк из маршрутов","slug":"возврат-строк-из-маршрутов","link":"#возврат-строк-из-маршрутов","children":[]},{"level":4,"title":"Создание пользовательских ответов","slug":"создание-пользовательских-ответов","link":"#создание-пользовательских-ответов","children":[]},{"level":3,"title":"Добавление заголовков к ответам","slug":"добавление-заголовков-к-ответам","link":"#добавление-заголовков-к-ответам","children":[]},{"level":3,"title":"Добавление cookies к ответам","slug":"добавление-cookies-к-ответам","link":"#добавление-cookies-к-ответам","children":[]}]},{"level":2,"title":"Другие типы ответов","slug":"другие-типы-ответов","link":"#другие-типы-ответов","children":[{"level":3,"title":"Ответы с представлениями","slug":"ответы-с-представлениями","link":"#ответы-с-представлениями","children":[]},{"level":3,"title":"JSON-ответы","slug":"json-ответы","link":"#json-ответы","children":[]},{"level":3,"title":"Загрузка файлов","slug":"загрузка-фаилов","link":"#загрузка-фаилов","children":[{"level":4,"title":"Потоковые загрузки","slug":"потоковые-загрузки","link":"#потоковые-загрузки","children":[]}]},{"level":3,"title":"Файловые ответы","slug":"фаиловые-ответы","link":"#фаиловые-ответы","children":[]}]},{"level":2,"title":"Перенаправления","slug":"перенаправления","link":"#перенаправления","children":[{"level":3,"title":"Возврат перенаправления с данными сессии","slug":"возврат-перенаправления-с-данными-сессии","link":"#возврат-перенаправления-с-данными-сессии","children":[{"level":4,"title":"Перенаправление на предыдущий URL","slug":"перенаправление-на-предыдущии-url","link":"#перенаправление-на-предыдущии-url","children":[]},{"level":4,"title":"Перенаправление на текущую страницу","slug":"перенаправление-на-текущую-страницу","link":"#перенаправление-на-текущую-страницу","children":[]}]}]},{"level":2,"title":"Макросы ответов","slug":"макросы-ответов","link":"#макросы-ответов","children":[]},{"level":2,"title":"Представления","slug":"представления","link":"#представления","children":[{"level":4,"title":"Передача данных в представления","slug":"передача-данных-в-представления","link":"#передача-данных-в-представления","children":[]},{"level":4,"title":"Передача вложенного представления в представление","slug":"передача-вложенного-представления-в-представление","link":"#передача-вложенного-представления-в-представление","children":[]},{"level":4,"title":"Определение существования представления","slug":"определение-существования-представления","link":"#определение-существования-представления","children":[]},{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/services/response-view.md","filePath":"3.x/ru/extend/services/response-view.md"}'),r={name:"3.x/ru/extend/services/response-view.md"};function k(d,n,g,h,v,m){const p=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[e(p),n[0]||(n[0]=s("h1",null,"Ответы и представления",-1)),e(o),n[1]||(n[1]=u(`<h2 id="базовые-ответы"><a href="#базовые-ответы" class="header-anchor">#</a> Базовые ответы</h2><p>Ответ может быть возвращён практически из любого PHP-метода, используемого страницей. Это включает все CMS-методы, содержащиеся в <a href="./../../cms/themes/layouts.html">жизненном цикле выполнения макета</a> и <a href="./../../cms/ajax/handlers.html">определениях AJAX-обработчиков</a>.</p><h4 id="возврат-строк-из-cms-метода"><a href="#возврат-строк-из-cms-метода" class="header-anchor">#</a> Возврат строк из CMS-метода</h4><p>Возврат строки из метода CMS-страницы, макета или компонента остановит процесс в этой точке и переопределит поведение по умолчанию, поэтому здесь будет отображена строка «Hello World» вместо отображения страницы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="возврат-строк-из-ajax-обработчиков"><a href="#возврат-строк-из-ajax-обработчиков" class="header-anchor">#</a> Возврат строк из AJAX-обработчиков</h4><p>Возврат строки из AJAX-обработчика добавит строку в коллекцию ответов, используя ключ по умолчанию <code>result</code>. Запрошенные фрагменты по-прежнему будут включены в ответ.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
    <span class="token comment">// [&#39;result&#39; =&gt; &#39;Hello World&#39;]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="возврат-строк-из-маршрутов"><a href="#возврат-строк-из-маршрутов" class="header-anchor">#</a> Возврат строк из маршрутов</h4><p>Возврат строки из <a href="./../system/routing.html">определения маршрута</a> действует так же, как CMS-метод, и отображает строку в качестве ответа.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="создание-пользовательских-ответов"><a href="#создание-пользовательских-ответов" class="header-anchor">#</a> Создание пользовательских ответов</h4><p>Для более надёжного решения возврат объекта <code>Response</code> предоставляет множество методов для построения HTTP-ответов. Мы рассмотрим эту тему подробнее в данной статье.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Page not found&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token number">404</span><span class="token punctuation">;</span>
<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$contents</span><span class="token punctuation">,</span> <span class="token variable">$statusCode</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="добавление-заголовков-к-ответам"><a href="#добавление-заголовков-к-ответам" class="header-anchor">#</a> Добавление заголовков к ответам</h3><p>Имейте в виду, что большинство методов ответа являются цепочечными, что позволяет строить ответы последовательно. Например, вы можете использовать метод <code>header</code> для добавления серии заголовков к ответу перед отправкой его пользователю:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-One&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-Two&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Практическим примером может быть возврат XML-ответа:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$xmlString</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="добавление-cookies-к-ответам"><a href="#добавление-cookies-к-ответам" class="header-anchor">#</a> Добавление cookies к ответам</h3><p>Метод <code>withCookie</code> позволяет легко прикреплять cookies к ответу. Например, вы можете использовать метод withCookie для генерации cookie и прикрепления его к экземпляру ответа:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>withCookie</code> принимает дополнительные необязательные аргументы, которые позволяют дополнительно настроить свойства вашего cookie:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">,</span> <span class="token variable">$path</span><span class="token punctuation">,</span> <span class="token variable">$domain</span><span class="token punctuation">,</span> <span class="token variable">$secure</span><span class="token punctuation">,</span> <span class="token variable">$httpOnly</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="другие-типы-ответов"><a href="#другие-типы-ответов" class="header-anchor">#</a> Другие типы ответов</h2><p>Фасад <code>Response</code> может использоваться для удобной генерации других типов экземпляров ответов.</p><h3 id="ответы-с-представлениями"><a href="#ответы-с-представлениями" class="header-anchor">#</a> Ответы с представлениями</h3><p>Если вам нужен доступ к методам класса <code>Response</code>, но вы хотите вернуть представление в качестве содержимого ответа, вы можете использовать метод <code>Response::view</code> для удобства:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">view</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::hello&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="json-ответы"><a href="#json-ответы" class="header-anchor">#</a> JSON-ответы</h3><p>Метод <code>json</code> автоматически установит заголовок <code>Content-Type</code> в application/json, а также преобразует заданный массив в JSON с помощью PHP-функции <code>json_encode</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите создать JSONP-ответ, вы можете использовать метод <code>json</code> в сочетании с <code>setCallback</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">setCallback</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;callback&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="загрузка-фаилов"><a href="#загрузка-фаилов" class="header-anchor">#</a> Загрузка файлов</h3><p>Метод <code>download</code> может использоваться для генерации ответа, который заставляет браузер пользователя загрузить файл по указанному пути (первый аргумент). Метод <code>download</code> опционально принимает имя файла (второй аргумент), которое определяет имя файла, видимое пользователю при загрузке, и массив HTTP-заголовков (третий аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">deleteFileAfterSend</span><span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Symfony HttpFoundation, который управляет загрузкой файлов, требует, чтобы загружаемый файл имел имя в ASCII-кодировке.</p></div><h4 id="потоковые-загрузки"><a href="#потоковые-загрузки" class="header-anchor">#</a> Потоковые загрузки</h4><p>В некоторых случаях вы можете захотеть превратить строковый ответ в загружаемый ответ без записи содержимого на диск. Используйте метод <code>streamDownload</code> для решения этой задачи. Метод принимает callback-функцию (первый аргумент), имя файла (второй аргумент) и необязательный массив заголовков (третий аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">streamDownload</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;CSV Contents...&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;export.csv&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="фаиловые-ответы"><a href="#фаиловые-ответы" class="header-anchor">#</a> Файловые ответы</h3><p>Метод <code>file</code> используется для отображения файла, такого как изображение или PDF, непосредственно в браузере пользователя вместо инициации загрузки. Этот метод принимает путь к файлу (первый аргумент) и массив заголовков (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="перенаправления"><a href="#перенаправления" class="header-anchor">#</a> Перенаправления</h2><p>Ответы перенаправления обычно являются экземплярами класса <code>Illuminate\\Http\\RedirectResponse</code> и содержат надлежащие заголовки, необходимые для перенаправления пользователя на другой URL. Самый простой способ сгенерировать экземпляр <code>RedirectResponse</code> — использовать метод <code>to</code> фасада <code>Redirect</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="возврат-перенаправления-с-данными-сессии"><a href="#возврат-перенаправления-с-данными-сессии" class="header-anchor">#</a> Возврат перенаправления с данными сессии</h3><p>Перенаправление на новый URL и <a href="./session.html">сохранение данных в сессии</a> обычно выполняются одновременно. Поэтому для удобства вы можете создать экземпляр <code>RedirectResponse</code> и сохранить данные в сессии в одной цепочке методов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Login Failed&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Поскольку метод <code>with</code> сохраняет данные в сессии, вы можете получить данные с помощью обычного метода <code>Session::get</code>.</p></div><h4 id="перенаправление-на-предыдущии-url"><a href="#перенаправление-на-предыдущии-url" class="header-anchor">#</a> Перенаправление на предыдущий URL</h4><p>Вы можете захотеть перенаправить пользователя на его предыдущее местоположение, например, после отправки формы. Вы можете сделать это с помощью метода <code>back</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="перенаправление-на-текущую-страницу"><a href="#перенаправление-на-текущую-страницу" class="header-anchor">#</a> Перенаправление на текущую страницу</h4><p>Иногда вы хотите просто обновить текущую страницу. Вы можете сделать это с помощью метода <code>refresh</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="макросы-ответов"><a href="#макросы-ответов" class="header-anchor">#</a> Макросы ответов</h2><p>Если вы хотите определить пользовательский ответ, который можно повторно использовать в различных маршрутах и контроллерах, вы можете использовать метод <code>Response::macro</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">macro</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;caps&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Функция <code>macro</code> принимает имя в качестве первого аргумента и Closure в качестве второго. Closure макроса будет выполнено при вызове имени макроса на классе <code>Response</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">caps</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете определять свои макросы в методе <code>boot</code> <a href="./../extending.html">файла регистрации плагина</a>. Альтернативно плагины могут предоставить файл с именем <strong>init.php</strong> в директории плагина, который вы можете использовать для размещения регистрации макросов.</p><h2 id="представления"><a href="#представления" class="header-anchor">#</a> Представления</h2><p>Представления — отличный способ хранить системную логику отображения, такую как разметка, используемая API или конечной точкой, или разметка, общая для CMS и панели управления. Представления также используются <a href="./../system/sending-mail.html">сервисом почты</a> для предоставления содержимого шаблонов по умолчанию. Представления обычно хранятся в директории <code>views</code> плагина.</p><p>Простое представление может выглядеть следующим образом:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.htm --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Представления также могут быть разобраны с использованием PHP-шаблонов с расширением <code>.php</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.php --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Это представление может быть возвращено в браузер с помощью метода <code>View::make</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Charlie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Первый аргумент — это «подсказка пути», которая содержит имя плагина, разделённое двумя двоеточиями <code>::</code>, за которым следует имя файла представления. Второй аргумент, переданный в <code>View::make</code>, — это массив данных, которые должны быть доступны в представлении.</p><div class="custom-block tip"><p>Подсказка пути чувствительна к регистру, и имя плагина всегда должно быть в нижнем регистре.</p></div><h4 id="передача-данных-в-представления"><a href="#передача-данных-в-представления" class="header-anchor">#</a> Передача данных в представления</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Using conventional approach</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Using magic methods</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В примере выше переменная <code>name</code> будет доступна из представления и будет содержать <code>Steve</code>. Как и выше, если вы хотите передать массив данных, вы можете сделать это в качестве второго аргумента метода <code>make</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Также возможно сделать часть данных доступной для всех представлений:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="передача-вложенного-представления-в-представление"><a href="#передача-вложенного-представления-в-представление" class="header-anchor">#</a> Передача вложенного представления в представление</h4><p>Иногда вы можете захотеть передать представление в другое представление. Например, имея вложенное представление, хранящееся по пути <code>plugins/acme/blog/views/child/view.php</code>, мы могли бы передать его в другое представление следующим образом:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вложенное представление затем может быть отрендерено из родительского представления:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="определение-существования-представления"><a href="#определение-существования-представления" class="header-anchor">#</a> Определение существования представления</h4><p>Если вам нужно проверить, существует ли представление, используйте метод <code>View::exists</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.customer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4>`,88)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"./../../cms/features/upload-download.html"},"Загрузка и скачивание")]),s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/responses",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Ответы Laravel"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const x=c(r,[["render",k]]);export{w as __pageData,x as default};
